def longestSharedByAll(words):
    ws = words.split(",")
    MOD = (1 << 61) - 1
    B = 911382323
    maxlen = max(len(w) for w in ws)
    PW = [1] * (maxlen + 1)
    for i in range(maxlen):
        PW[i + 1] = PW[i] * B % MOD
    pref = []
    for w in ws:
        H = [0] * (len(w) + 1)
        for i, c in enumerate(w):
            H[i + 1] = (H[i] * B + ord(c)) % MOD
        pref.append(H)

    def hashes(idx, L):
        H = pref[idx]
        return {(H[j + L] - H[j] * PW[L]) % MOD for j in range(len(H) - L)}

    def feasible(L):
        common = None
        for idx in range(len(ws)):
            cur = hashes(idx, L)
            common = cur if common is None else common & cur
            if not common:
                return False
        return True

    lo, hi = 0, min(len(w) for w in ws)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
